class TeamRow extends DataClass implements Insertable<TeamRow> {
  final String sourceName;
  final String sourceUrl;
  final String? sourceRecordId;
  final DateTime fetchedAt;
  final DateTime? verifiedAt;
  final String? contentHash;
  final String qualityStatus;
  final String licenseStatus;
  final String visibility;
  final bool isDemo;

  /// Tombstone. Records that vanish upstream are marked here and hidden by
  /// policy; they are never hard-deleted, so a source glitch cannot silently
  /// erase a user's saved game.
  final DateTime? deletedAt;
  final String id;
  final String name;
  final String? shortName;
  final String? region;
  final String? city;
  final int? foundedYear;
  final String? introduction;
  final String recruitment;
  final String? recruitmentTarget;
  final String? homeVenueId;
  final String? practiceArea;
  final String? officialUrl;
  final String? contactUrl;
  final String? logoUrl;
  final String logoLicense;
  final String? colorHex;

  /// Pre-computed search key: whitespace-stripped name plus its 초성 (Korean
  /// initial consonants), so "ㅅㅇ" matches "서울". Filled by the mapper.
  final String searchKey;
  const TeamRow({
    required this.sourceName,
    required this.sourceUrl,
    this.sourceRecordId,
    required this.fetchedAt,
    this.verifiedAt,
    this.contentHash,
    required this.qualityStatus,
    required this.licenseStatus,
    required this.visibility,
