class PersonRow extends DataClass implements Insertable<PersonRow> {
  final String sourceName;
  final String sourceUrl;
  final String? sourceRecordId;
  final DateTime fetchedAt;
  final DateTime? verifiedAt;
  final String? contentHash;
  final String qualityStatus;
  final String licenseStatus;
  final String visibility;
  final bool isDemo;

  /// Tombstone. Records that vanish upstream are marked here and hidden by
  /// policy; they are never hard-deleted, so a source glitch cannot silently
  /// erase a user's saved game.
  final DateTime? deletedAt;
  final String id;
  final String name;
  final bool isMinor;
  final String? photoUrl;
  final String photoLicense;
  final String searchKey;
  const PersonRow({
    required this.sourceName,
    required this.sourceUrl,
    this.sourceRecordId,
    required this.fetchedAt,
    this.verifiedAt,
    this.contentHash,
    required this.qualityStatus,
    required this.licenseStatus,
    required this.visibility,
    required this.isDemo,
    this.deletedAt,
    required this.id,
    required this.name,
    required this.isMinor,
    this.photoUrl,
    required this.photoLicense,
    required this.searchKey,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['source_name'] = Variable<String>(sourceName);
    map['source_url'] = Variable<String>(sourceUrl);
    if (!nullToAbsent || sourceRecordId != null) {
      map['source_record_id'] = Variable<String>(sourceRecordId);
    }
    map['fetched_at'] = Variable<DateTime>(fetchedAt);
    if (!nullToAbsent || verifiedAt != null) {
      map['verified_at'] = Variable<DateTime>(verifiedAt);
    }
    if (!nullToAbsent || contentHash != null) {
      map['content_hash'] = Variable<String>(contentHash);
    }
    map['quality_status'] = Variable<String>(qualityStatus);
    map['license_status'] = Variable<String>(licenseStatus);
    map['visibility'] = Variable<String>(visibility);
    map['is_demo'] = Variable<bool>(isDemo);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['is_minor'] = Variable<bool>(isMinor);
    if (!nullToAbsent || photoUrl != null) {
      map['photo_url'] = Variable<String>(photoUrl);
    }
    map['photo_license'] = Variable<String>(photoLicense);
    map['search_key'] = Variable<String>(searchKey);
    return map;
  }

  PeopleCompanion toCompanion(bool nullToAbsent) {
    return PeopleCompanion(
      sourceName: Value(sourceName),
      sourceUrl: Value(sourceUrl),
      sourceRecordId: sourceRecordId == null && nullToAbsent
          ? const Value.absent()
          : Value(sourceRecordId),
      fetchedAt: Value(fetchedAt),
      verifiedAt: verifiedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(verifiedAt),
      contentHash: contentHash == null && nullToAbsent
          ? const Value.absent()
          : Value(contentHash),
      qualityStatus: Value(qualityStatus),
      licenseStatus: Value(licenseStatus),
      visibility: Value(visibility),
      isDemo: Value(isDemo),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      id: Value(id),
      name: Value(name),
      isMinor: Value(isMinor),
      photoUrl: photoUrl == null && nullToAbsent
          ? const Value.absent()
          : Value(photoUrl),
      photoLicense: Value(photoLicense),
      searchKey: Value(searchKey),
    );
  }

  factory PersonRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
