    required this.awayTeamId,
    this.seasonId,
    this.stageId,
    this.competitionId,
    this.venueId,
    this.homeScore,
    this.awayScore,
    required this.localTimeZone,
    this.round,
    this.summary,
    this.officialDetailUrl,
    this.statusNote,
    required this.dedupeKey,
  });
