class PitchingStatRow extends DataClass implements Insertable<PitchingStatRow> {
  final String gameId;
  final String personId;
  final String teamId;
  final String playerName;

  /// Outs, not decimal innings, so 5⅓ is exactly 16.
  final int outsRecorded;
  final int hitsAllowed;
  final int runsAllowed;
  final int earnedRuns;
  final int walks;
  final int strikeouts;
  final int homeRunsAllowed;
  final String? decision;
  const PitchingStatRow({
    required this.gameId,
    required this.personId,
    required this.teamId,
    required this.playerName,
    required this.outsRecorded,
    required this.hitsAllowed,
    required this.runsAllowed,
    required this.earnedRuns,
    required this.walks,
    required this.strikeouts,
    required this.homeRunsAllowed,
    this.decision,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['game_id'] = Variable<String>(gameId);
    map['person_id'] = Variable<String>(personId);
    map['team_id'] = Variable<String>(teamId);
    map['player_name'] = Variable<String>(playerName);
    map['outs_recorded'] = Variable<int>(outsRecorded);
    map['hits_allowed'] = Variable<int>(hitsAllowed);
    map['runs_allowed'] = Variable<int>(runsAllowed);
    map['earned_runs'] = Variable<int>(earnedRuns);
    map['walks'] = Variable<int>(walks);
    map['strikeouts'] = Variable<int>(strikeouts);
    map['home_runs_allowed'] = Variable<int>(homeRunsAllowed);
    if (!nullToAbsent || decision != null) {
      map['decision'] = Variable<String>(decision);
    }
    return map;
  }

  PitchingStatsCompanion toCompanion(bool nullToAbsent) {
    return PitchingStatsCompanion(
      gameId: Value(gameId),
      personId: Value(personId),
      teamId: Value(teamId),
      playerName: Value(playerName),
      outsRecorded: Value(outsRecorded),
      hitsAllowed: Value(hitsAllowed),
      runsAllowed: Value(runsAllowed),
      earnedRuns: Value(earnedRuns),
      walks: Value(walks),
      strikeouts: Value(strikeouts),
      homeRunsAllowed: Value(homeRunsAllowed),
      decision: decision == null && nullToAbsent
          ? const Value.absent()
          : Value(decision),
    );
  }

  factory PitchingStatRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return PitchingStatRow(
      gameId: serializer.fromJson<String>(json['gameId']),
      personId: serializer.fromJson<String>(json['personId']),
      teamId: serializer.fromJson<String>(json['teamId']),
      playerName: serializer.fromJson<String>(json['playerName']),
      outsRecorded: serializer.fromJson<int>(json['outsRecorded']),
      hitsAllowed: serializer.fromJson<int>(json['hitsAllowed']),
      runsAllowed: serializer.fromJson<int>(json['runsAllowed']),
      earnedRuns: serializer.fromJson<int>(json['earnedRuns']),
      walks: serializer.fromJson<int>(json['walks']),
      strikeouts: serializer.fromJson<int>(json['strikeouts']),
      homeRunsAllowed: serializer.fromJson<int>(json['homeRunsAllowed']),
      decision: serializer.fromJson<String?>(json['decision']),
    );
  }
  @override
