          ..write('gameId: $gameId, ')
          ..write('personId: $personId, ')
          ..write('teamId: $teamId, ')
          ..write('playerName: $playerName, ')
          ..write('outsRecorded: $outsRecorded, ')
          ..write('hitsAllowed: $hitsAllowed, ')
          ..write('runsAllowed: $runsAllowed, ')
