class ArticleRow extends DataClass implements Insertable<ArticleRow> {
  final String sourceName;
  final String sourceUrl;
  final String? sourceRecordId;
  final DateTime fetchedAt;
  final DateTime? verifiedAt;
  final String? contentHash;
  final String qualityStatus;
  final String licenseStatus;
  final String visibility;
  final bool isDemo;

  /// Tombstone. Records that vanish upstream are marked here and hidden by
  /// policy; they are never hard-deleted, so a source glitch cannot silently
  /// erase a user's saved game.
  final DateTime? deletedAt;
  final String id;
  final String title;
  final String url;
  final DateTime publishedAt;
  final String? outlet;

  /// Only the snippet the search API returned. Never scraped body text.
  final String? summary;
  final String teamIds;
  final String competitionIds;
  final bool isOfficialNotice;

  /// Set once the article has been folded into a story cluster.
  final String? storyClusterId;
  const ArticleRow({
    required this.sourceName,
    required this.sourceUrl,
    this.sourceRecordId,
    required this.fetchedAt,
    this.verifiedAt,
    this.contentHash,
    required this.qualityStatus,
    required this.licenseStatus,
    required this.visibility,
    required this.isDemo,
    this.deletedAt,
    required this.id,
    required this.title,
    required this.url,
    required this.publishedAt,
    this.outlet,
    this.summary,
    required this.teamIds,
    required this.competitionIds,
    required this.isOfficialNotice,
    this.storyClusterId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['source_name'] = Variable<String>(sourceName);
    map['source_url'] = Variable<String>(sourceUrl);
    if (!nullToAbsent || sourceRecordId != null) {
      map['source_record_id'] = Variable<String>(sourceRecordId);
    }
    map['fetched_at'] = Variable<DateTime>(fetchedAt);
    if (!nullToAbsent || verifiedAt != null) {
      map['verified_at'] = Variable<DateTime>(verifiedAt);
    }
    if (!nullToAbsent || contentHash != null) {
      map['content_hash'] = Variable<String>(contentHash);
    }
    map['quality_status'] = Variable<String>(qualityStatus);
    map['license_status'] = Variable<String>(licenseStatus);
    map['visibility'] = Variable<String>(visibility);
    map['is_demo'] = Variable<bool>(isDemo);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['id'] = Variable<String>(id);
    map['title'] = Variable<String>(title);
    map['url'] = Variable<String>(url);
    map['published_at'] = Variable<DateTime>(publishedAt);
    if (!nullToAbsent || outlet != null) {
      map['outlet'] = Variable<String>(outlet);
    }
    if (!nullToAbsent || summary != null) {
      map['summary'] = Variable<String>(summary);
    }
    map['team_ids'] = Variable<String>(teamIds);
    map['competition_ids'] = Variable<String>(competitionIds);
    map['is_official_notice'] = Variable<bool>(isOfficialNotice);
    if (!nullToAbsent || storyClusterId != null) {
      map['story_cluster_id'] = Variable<String>(storyClusterId);
    }
    return map;
  }

