class FeaturedTopicRow extends DataClass
    implements Insertable<FeaturedTopicRow> {
  final String sourceName;
  final String sourceUrl;
  final String? sourceRecordId;
  final DateTime fetchedAt;
  final DateTime? verifiedAt;
  final String? contentHash;
  final String qualityStatus;
  final String licenseStatus;
  final String visibility;
  final bool isDemo;

  /// Tombstone. Records that vanish upstream are marked here and hidden by
  /// policy; they are never hard-deleted, so a source glitch cannot silently
  /// erase a user's saved game.
  final DateTime? deletedAt;
  final DateTime publishedAt;
  final String summaryMethod;
  final String reviewStatus;
  final String spoilerLevel;
  final DateTime? generatedAt;
  final int coverageObserved;
  final int coverageExpected;
  final String? coverageNote;
  final String id;
  final String kind;
  final String title;
  final String? subtitle;

  /// Lower wins. Null falls back to the kind's default priority, which is what
  /// makes an ended broadcast fall through to the next topic automatically.
  final int? priority;
  final String? programId;
  final String? competitionId;
  final String? storyClusterId;
  final String? guideId;
  final String? heroImageUrl;
  final String heroImageLicense;
  final DateTime? activeFrom;
  final DateTime? activeUntil;
  const FeaturedTopicRow({
    required this.sourceName,
    required this.sourceUrl,
    this.sourceRecordId,
    required this.fetchedAt,
    this.verifiedAt,
    this.contentHash,
    required this.qualityStatus,
    required this.licenseStatus,
    required this.visibility,
    required this.isDemo,
    this.deletedAt,
    required this.publishedAt,
    required this.summaryMethod,
    required this.reviewStatus,
    required this.spoilerLevel,
    this.generatedAt,
    required this.coverageObserved,
    required this.coverageExpected,
    this.coverageNote,
    required this.id,
    required this.kind,
    required this.title,
    this.subtitle,
    this.priority,
    this.programId,
    this.competitionId,
    this.storyClusterId,
    this.guideId,
    this.heroImageUrl,
    required this.heroImageLicense,
    this.activeFrom,
    this.activeUntil,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['source_name'] = Variable<String>(sourceName);
    map['source_url'] = Variable<String>(sourceUrl);
    if (!nullToAbsent || sourceRecordId != null) {
      map['source_record_id'] = Variable<String>(sourceRecordId);
    }
    map['fetched_at'] = Variable<DateTime>(fetchedAt);
    if (!nullToAbsent || verifiedAt != null) {
      map['verified_at'] = Variable<DateTime>(verifiedAt);
    }
    if (!nullToAbsent || contentHash != null) {
      map['content_hash'] = Variable<String>(contentHash);
    }
    map['quality_status'] = Variable<String>(qualityStatus);
    map['license_status'] = Variable<String>(licenseStatus);
    map['visibility'] = Variable<String>(visibility);
    map['is_demo'] = Variable<bool>(isDemo);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['published_at'] = Variable<DateTime>(publishedAt);
    map['summary_method'] = Variable<String>(summaryMethod);
    map['review_status'] = Variable<String>(reviewStatus);
    map['spoiler_level'] = Variable<String>(spoilerLevel);
    if (!nullToAbsent || generatedAt != null) {
      map['generated_at'] = Variable<DateTime>(generatedAt);
    }
    map['coverage_observed'] = Variable<int>(coverageObserved);
    map['coverage_expected'] = Variable<int>(coverageExpected);
    if (!nullToAbsent || coverageNote != null) {
      map['coverage_note'] = Variable<String>(coverageNote);
    }
    map['id'] = Variable<String>(id);
    map['kind'] = Variable<String>(kind);
    map['title'] = Variable<String>(title);
    if (!nullToAbsent || subtitle != null) {
      map['subtitle'] = Variable<String>(subtitle);
    }
    if (!nullToAbsent || priority != null) {
      map['priority'] = Variable<int>(priority);
    }
    if (!nullToAbsent || programId != null) {
      map['program_id'] = Variable<String>(programId);
    }
    if (!nullToAbsent || competitionId != null) {
      map['competition_id'] = Variable<String>(competitionId);
    }
    if (!nullToAbsent || storyClusterId != null) {
      map['story_cluster_id'] = Variable<String>(storyClusterId);
    }
    if (!nullToAbsent || guideId != null) {
