    }
    if (!nullToAbsent || activeUntil != null) {
      map['active_until'] = Variable<DateTime>(activeUntil);
    }
    return map;
  }

  FeaturedTopicsCompanion toCompanion(bool nullToAbsent) {
    return FeaturedTopicsCompanion(
      sourceName: Value(sourceName),
