class EpisodeRecapRow extends DataClass implements Insertable<EpisodeRecapRow> {
  final String sourceName;
  final String sourceUrl;
  final String? sourceRecordId;
  final DateTime fetchedAt;
  final DateTime? verifiedAt;
  final String? contentHash;
  final String qualityStatus;
  final String licenseStatus;
  final String visibility;
  final bool isDemo;

  /// Tombstone. Records that vanish upstream are marked here and hidden by
  /// policy; they are never hard-deleted, so a source glitch cannot silently
  /// erase a user's saved game.
  final DateTime? deletedAt;
  final DateTime publishedAt;
  final String summaryMethod;
  final String reviewStatus;
  final String spoilerLevel;
  final DateTime? generatedAt;
  final int coverageObserved;
  final int coverageExpected;
  final String? coverageNote;
  final String id;
  final String episodeId;

  /// Written to be spoiler-free; shown when the user hides results.
  final String? teaser;
